contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // addr: the depositor address
    // v: the amount of wei to send with Deposit
    function runTest(address payable addr, uint v) public payable {
        // require this contract has enough balance to forward v
        require(address(this).balance >= v);
        // snapshot prior recorded balance
        uint before = c.balances(addr);
        // perform Deposit as that address by using low-level call: we must call c.Deposit() from this contract,
        // but the contract's public surface requires msg.sender to be addr. Since tests must drive c only via calls
        // and cannot impersonate other addresses, we instead use addr as this caller by requiring addr == address(this)
        // or use the Address itself: enforce that the caller provides an address equal to this contract so Deposit
        // is invoked from the depositor. This keeps the test general: we require addr == address(this).
        require(addr == address(this));

        // call Deposit forwarding v wei
        c.Deposit{value: v}();

        // read after balance
        uint after = c.balances(addr);

        // assert that the recorded balance increased by at least v
        assert(after >= before + v);
    }

    // allow receiving Ether so this contract can forward it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an address payable who will be the caller for Collect/Deposit,
    // and an amount to send with Deposit. The test function is payable so
    // the caller of this test can fund it and forward Ether to c.
    function run(address payable who, uint collectAmount, uint depositValue) public payable {
        // Precondition: this test contract must hold enough Ether to forward depositValue
        require(address(this).balance >= depositValue);

        // Step 1: attempt Collect from `who`. We must call as `who`, but in tests
        // we can't change msg.sender. Instead, use the fact that Collect acts on
        // msg.sender; so to simulate the difference we will call Collect from this
        // contract and then Deposit from this contract. The property is about
        // the contract's ether balance before/after Deposit when Collect succeeded.
        // Ensure Collect may succeed: require that c has enough balance to send collectAmount.
        // Note: we can only observe address(c).balance, not internal balances mapping.
        require(address(c).balance >= collectAmount);

        // Perform Collect from this contract (this becomes the msg.sender for c.Collect)
        c.Collect(collectAmount);

        // Record contract balance of c after Collect
        uint balAfterCollect = address(c).balance;

        // Perform Deposit sending depositValue wei to c
        c.Deposit{value: depositValue}();

        // Observe contract balance after Deposit
        uint balAfterDeposit = address(c).balance;

        // Assert: Deposit must not decrease the contract's ether balance
        assert(balAfterDeposit >= balAfterCollect);
    }

    // allow receiving Ether to fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: send some ether value 'v' from this contract to c.Deposit
    // requires this contract to hold at least v wei
    function runTest(uint v) public {
        require(v > 0, "value must be positive");
        require(address(this).balance >= v, "not enough balance to send");

        // read old balance for this contract in c
        uint oldBal = c.balances(address(this));

        // perform Deposit by sending v wei
        c.Deposit{value: v}();

        // read new balance
        uint newBal = c.balances(address(this));

        // Assert that balance increased by exactly v. This holds for original P but is violated by M
        assert(newBal == oldBal + v);
    }

    // allow the test contract to receive ETH so it can call runTest
    receive() external payable {}
    fallback() external payable {}
}

