pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep amount in a reasonable range and non-zero to exercise deposit
        amt = bound(amt, 1, 1 ether);
        vm.assume(depositor != address(0));

        // Fund depositor and call Deposit() as depositor
        vm.deal(depositor, amt);
        uint256 before = c.balances(depositor);

        bool ok;
        vm.prank(depositor);
        try c.Deposit{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: for the reference contract, if Deposit call succeeded, the balance is increased by amt;
        // if Deposit reverted, balance unchanged. We assert this single observable fact.
        if (ok) {
            assertTrue(c.balances(depositor) == before + amt);
        } else {
            assertTrue(c.balances(depositor) == before);
        }
    }
}

