pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount
    // We keep domain wide but require non-zero amounts to exercise behavior
    function testFuzz_property(address depositor, uint256 amount) public {
        // admissible domain: depositor should be non-zero EOA and amount fits in balance
        vm.assume(depositor != address(0));
        // bound amount to a reasonable range so vm.deal can fund
        amount = bound(amount, 1, 1 ether);

        // Deploy a malicious Log that reverts in AddMessage to simulate the adversarial counterparty
        ReverterLog badLog = new ReverterLog();
        // set the contract's Log file to the reverter
        c.SetLogFile(address(badLog));

        // fund the depositor so the deposit can be sent
        vm.deal(depositor, amount);

        // record old balance according to contract getter
        uint256 oldBal = c.balances(depositor);

        // Call Deposit from depositor, catching whether it reverts
        bool ok;
        vm.prank(depositor);
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees: if Deposit returned (ok==true) then balances == old + amount.
        // The mutant that logs before updating and whose Log.AddMessage reverts will cause Deposit to revert
        // (or, if logging before update leads to loss of update in some flows, the balances may not have increased)
        // We assert the universal property on the reference: if call succeeded, recorded balance equals old + amount.
        uint256 newBal = c.balances(depositor);
        assertTrue(!ok || newBal == oldBal + amount);
    }
}

// Adversarial helper: a Log contract whose AddMessage reverts to exercise the timing difference
contract ReverterLog {
    // match AddMessage signature in original
    function AddMessage(address, uint, string memory) public pure {
        revert("bad log");
    }
}

