pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: For any caller and deposit amount, if Deposit() returns (doesn't revert),
    // then balances(caller) has increased by exactly the deposited amount.
    // We fuzz caller and amount. To allow the fuzzer to pick an address that is a contract
    // which reverts during Log.AddMessage, we deploy a Reverter and pass its address to C
    // via SetLogFile. We still fuzz the depositor and amount so the fuzzer can find the
    // scenario where the mutant differs.
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep domain reasonable but wide
        vm.assume(depositor != address(0));
        // amount up to some large value but not overflowing vm.deal
        amount = bound(amount, 0, 1 ether);

        // Deploy a helper that will revert on receiving AddMessage calls
        Reverter rev = new Reverter();

        // Set the Log file to the reverter contract (this replicates the adversarial counterparty)
        c.SetLogFile(address(rev));

        // Fund depositor so they can send 'amount'
        vm.deal(depositor, amount);

        // record old balance from contract's storage
        uint256 oldBal = c.balances(depositor);

        // perform the deposit as the depositor; capture whether the call succeeded
        bool ok;
        vm.startPrank(depositor);
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The property: if Deposit returned successfully, the recorded balances(depositor)
        // must equal oldBal + amount. This holds for the reference contract for all inputs.
        // The mutant that logs before updating can cause the call to revert or succeed but
        // leave balances unchanged depending on external behavior; the fuzzer should find a case
        // (some depositor and amount) where the mutant violates the assertion.
        if (ok) {
            assertTrue(c.balances(depositor) == oldBal + amount);
        } else {
            // If Deposit reverted, the property is about successful completions only; pass.
            assertTrue(true);
        }
    }
}

// adversarial helper that will revert on any call (simulates Log.AddMessage reverting)
contract Reverter {
    fallback() external payable {
        revert("revert from log");
    }
    receive() external payable {
        revert("revert from log");
    }
}

