pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and amount
    // We deploy a malicious log contract that re-enters C during AddMessage to exploit ordering.
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount within reasonable gas/ETH bounds
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // deploy a reentrant Log that will call back into c.Deposit (to exploit ordering in mutant)
        ReentrantLog mal = new ReentrantLog(address(c));

        // set the log file in c to our malicious log
        // must be done before initialization
        c.SetLogFile(address(mal));

        // fund depositor and the malicious log so it can forward calls if needed
        vm.deal(depositor, amount);
        vm.deal(address(mal), 1 ether);

        // record prior balance entry for depositor
        uint256 before = c.balances(depositor);

        // make the malicious log know which depositor to re-enter as (it will use its own stored depositor)
        mal.setVictim(depositor);

        // perform the deposit as depositor
        vm.prank(depositor);
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: whenever Deposit() returns (ok == true), the depositor's
        // recorded balance must equal before + amount in the correct reference C.
        // The mutant (logging before update) can be made to violate this for some fuzzed inputs
        // (via the reentrant/malicious log). This single assert distinguishes the mutant.
        if (ok) {
            assertTrue(c.balances(depositor) == before + amount);
        } else {
            // If Deposit reverted, we still must hold the universal property vacuously. We assert true by
            // checking that the balance did not increase (deposit not applied). Keep this broad.
            assertTrue(c.balances(depositor) == before);
        }
    }
}

// Malicious Log that re-enters C during AddMessage to exploit logging-before-update ordering
contract ReentrantLog {
    address public target;
    address public victim;
    constructor(address _t) payable {
        target = _t;
    }
    function setVictim(address _v) public {
        victim = _v;
    }
    // mimic the LogFile.AddMessage signature
    function AddMessage(address _adr, uint _val, string memory _data) public {
        // re-enter the C contract as the victim: call Deposit with small value forwarded from this contract
        // If the target contract logs before updating (mutant), reentrancy can observe differing balances
        // and lead to the mutant leaving balances unchanged while calls succeed.
        // We send 0 value to avoid affecting ETH balances, but calling Deposit can still exercise ordering
        // if Deposit uses msg.sender relationships. To ensure activity, we call no value deposit.
        // Use low-level call to avoid revert bubbling.
        (bool s,) = target.call(abi.encodeWithSignature("Deposit()"));
        s; // silence
    }

    // accept ether to be able to forward or pay if needed
    receive() external payable {}
}

