pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MaliciousLog mal;

    function setUp() public { 
        c = new C();
        // deploy a malicious log that will revert when asked
        mal = new MaliciousLog();
        // set the contract's Log to our malicious one before initialization
        c.SetLogFile(address(mal));
    }

    // General rule: For any depositor and deposit amount, if Deposit() returns (does not revert),
    // then c.balances(depositor) == old_balance + amount. The mutant that logs before updating can be
    // broken by a Log.AddMessage that reverts; the reference C updates balance before calling Log,
    // so with a reverting Log the reference's Deposit will revert but we test the case where
    // logging is arranged to revert only for certain callers or via behavior — here we instead
    // make the malicious Log succeed but re-enter and revert the logging call after it's observed
    // so that ordering matters. To trigger the difference we use a reentering malicious log that
    // during AddMessage reenters Deposit on the same depositor. The correct contract has already
    // increased the balance before the AddMessage call, so reentrancy does not cause lost funds; the
    // mutant (which logs before updating) will be reentered with old balance and may cause observable
    // difference. The fuzzer supplies depositor and amount.

    function testFuzz_property(address depositor, uint256 amount) public {
        // admissible domain: depositor must not be zero and amount small enough to fund
        vm.assume(depositor != address(0));
        // bound the amount to avoid overflow in test harness and to give enough balance
        amount = bound(amount, 1, 1 ether);

        // Fund depositor
        vm.deal(depositor, amount);

        // Configure malicious log to reenter once when AddMessage is called by c
        mal.setTarget(address(c));
        mal.setReenter(true);

        // Make depositor call Deposit() paying `amount`. Use vm.prank to send from depositor
        vm.prank(depositor);
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: for the correct reference contract C (which this test is run against),
        // Deposit either reverts (ok==false) or, if it returned, the balance equals old + amount.
        // We cannot read the old balance after the fact, so we recreate it by querying balance before
        // doing the call would be ideal, but the test must have a single assertion reading c.
        // Instead, we rely on the fact that for the reference contract, whenever Deposit returns true,
        // the recorded balance equals the contract's public balances(depositor) which must be >= amount
        // and equal to the deposit because we started from 0 in this test setup (no prior deposits)
        // — to ensure starting from 0, we avoid any prior deposits.

        // Ensure initial balance was zero by construction: we never deposited from depositor before.
        // Now assert: if call succeeded, the contract's balances(depositor) == amount.
        if (ok) {
            assertTrue(c.balances(depositor) == amount);
        } else {
            // If the call reverted, the invariant "for any successful Deposit" is vacuously true;
            // we assert that deposit did not incorrectly report success while leaving balance unchanged
            // by asserting a true constant in revert case is not allowed. So still assert something about c:
            // we assert that balances(depositor) == 0 when Deposit reverted (reference preserves no change).
            assertTrue(c.balances(depositor) == 0);
        }
    }
}

// Malicious log: on AddMessage it will reenter c.Deposit() once to create a reentrancy scenario.
contract MaliciousLog {
    address target;
    bool doReenter;
    bool reentered;

    function setTarget(address _t) public { target = _t; }
    function setReenter(bool v) public { doReenter = v; }

    fallback() external payable {}

    function AddMessage(address _adr, uint _val, string memory _data) public {
        if (doReenter && !reentered) {
            reentered = true;
            // attempt reentrancy: call Deposit on the target, sending 0 value so it exercises the path
            // Note: reentrancy will behave differently depending on whether target updated balance before
            // or after logging; this distinguishes the mutant.
            (bool s,) = target.call(abi.encodeWithSignature("Deposit()"));
            // ignore result
        }
        // otherwise behave normally (no storage changes here)
    }
}

